def maxProfit(prices: list[int]) -> int:
    profit = 0
    for day in range(1, len(prices)):
        change = prices[day] - prices[day - 1]
        # 连续上涨区间可以拆成每一段正的相邻差值。
        if change > 0:
            profit += change
    return profit

code.cpp:
int maxProfit(vector<int>& prices) {
    int profit = 0;
    for (int day = 1; day < static_cast<int>(prices.size()); ++day) {
        int change = prices[day] - prices[day - 1];
        // 只捕获上涨；多个正差会还原为整段上涨利润。
        if (change > 0) profit += change;
    }
    return profit;
}

