from bisect import bisect_left

def lengthOfLIS(nums: list[int]) -> int:
    tails: list[int] = []
    for num in nums:
        # tails[k] 是长度 k + 1 的候选序列所能拥有的最小结尾。
        slot = bisect_left(tails, num)
        if slot == len(tails):
            tails.append(num)
        else:
            tails[slot] = num
    return len(tails)

code.cpp:
int lengthOfLIS(const vector<int>& nums) {
    vector<int> tails;
    for (int num : nums) {
        // 找到第一个不小于 num 的结尾位置。
        auto slot = lower_bound(tails.begin(), tails.end(), num);
        if (slot == tails.end()) {
            tails.push_back(num);
        } else {
            *slot = num;
        }
    }
    return static_cast<int>(tails.size());
}

